#include <iostream>
#include <memory>
#include <string>
#include <vector>

// Base class representing any visual entity in the game
class SpaceObject {
public:
    explicit SpaceObject(std::string name) : name_{std::move(name)} {}
    virtual ~SpaceObject() = default; // Essential for base classes

    // Polymorphic interface
    virtual void draw() const {
        std::cout << "Generic SpaceObject [" << name_ << "] drawn.\n";
    }

    const std::string& getName() const noexcept {
        return name_;
    }

private:
    std::string name_;
};

// Derived class 1
class Martian : public SpaceObject {
public:
    Martian() : SpaceObject("Martian") {}

    void draw() const override {
        std::cout << "Drawing Martian: Red alien with dual antennae.\n";
    }
};

// Derived class 2
class SpaceShip : public SpaceObject {
public:
    SpaceShip() : SpaceObject("SpaceShip") {}

    void draw() const override {
        std::cout << "Drawing SpaceShip: Silver flying saucer.\n";
    }
};

// Derived class 3 added cleanly without changing the screen renderer
class LaserBeam : public SpaceObject {
public:
    LaserBeam() : SpaceObject("LaserBeam") {}

    void draw() const override {
        std::cout << "Drawing LaserBeam: Bright red high-energy beam across screen.\n";
    }
};

// Extensible client function operating "in the general"
void renderScreen(const std::vector<std::unique_ptr<SpaceObject>>& scene) {
    std::cout << "--- Refreshing Screen ---\n";
    for (const auto& objPtr : scene) {
        // Common message dispatched polymorphically via base-class pointer
        objPtr->draw();
    }
}

int main() {
    std::vector<std::unique_ptr<SpaceObject>> scene;
    scene.push_back(std::make_unique<Martian>());
    scene.push_back(std::make_unique<SpaceShip>());
    scene.push_back(std::make_unique<LaserBeam>());

    renderScreen(scene);
    return 0;
}

#include <iomanip>
#include <iostream>
#include <string>

// Base class: CommissionEmployee
class CommissionEmployee {
public:
    CommissionEmployee(std::string first, std::string last, std::string ssn,
                       double sales, double rate)
        : firstName_{std::move(first)}, lastName_{std::move(last)},
          socialSecurityNumber_{std::move(ssn)}, grossSales_{sales}, commissionRate_{rate} {}

    // Note: Non-virtual function demonstrating static binding behavior
    void print() const {
        std::cout << "commission employee: " << firstName_ << " " << lastName_ << "\n"
                  << "social security number: " << socialSecurityNumber_ << "\n"
                  << "gross sales: " << grossSales_ << "\n"
                  << "commission rate: " << commissionRate_;
    }

private:
    std::string firstName_;
    std::string lastName_;
    std::string socialSecurityNumber_;
    double grossSales_;
    double commissionRate_;
};

// Derived class: BasePlusCommissionEmployee
class BasePlusCommissionEmployee : public CommissionEmployee {
public:
    BasePlusCommissionEmployee(std::string first, std::string last, std::string ssn,
                               double sales, double rate, double salary)
        : CommissionEmployee(std::move(first), std::move(last), std::move(ssn), sales, rate),
          baseSalary_{salary} {}

    // Redefined non-virtual print()
    void print() const {
        std::cout << "base-salaried ";
        CommissionEmployee::print();
        std::cout << "\nbase salary: " << baseSalary_;
    }

private:
    double baseSalary_;
};

int main() {
    std::cout << std::fixed << std::setprecision(2);

    CommissionEmployee baseEmp{"Sue", "Jones", "222-22-2222", 10000.0, 0.06};
    BasePlusCommissionEmployee derivedEmp{"Bob", "Lewis", "333-33-3333", 5000.0, 0.04, 300.0};

    // 1. Aim base pointer at base object
    CommissionEmployee* basePtr = &baseEmp;
    std::cout << "1. Base pointer to base object:\n";
    basePtr->print();
    std::cout << "\n\n";

    // 2. Aim derived pointer at derived object
    BasePlusCommissionEmployee* derivedPtr = &derivedEmp;
    std::cout << "2. Derived pointer to derived object:\n";
    derivedPtr->print();
    std::cout << "\n\n";

    // 3. Aim base pointer at derived object (is-a relationship)
    basePtr = &derivedEmp;
    std::cout << "3. Base pointer to derived object (static binding to base version):\n";
    basePtr->print(); // Calls CommissionEmployee::print() because print is non-virtual
    std::cout << "\n";

    return 0;
}
